head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > P > ampm]<br/>오전/오후 컬럼에 표시할 라벨을 콤마(',')로 구분하여 설정합니다.<br/>calendarValueType 속성이 'yearMonthDateTime' 또는 'hourMinute' 인 경우에만 동작합니다.",
    "validation" : [
        "오전/오후 컬럼에 표시할 라벨을 콤마(',')로 구분하여 설정합니다.",
        "오전, 오후 순서로 2개의 라벨을 콤마(',')로 구분하여 설정합니다.",
        "값을 설정하지 않으면 '오전,오후'가 설정됩니다.",
        "calendarValueType 속성이 'yearMonthDateTime' 인 경우에 동작합니다.",
        "calendarValueType 속성이 'hourMinute' 인 경우에 동작합니다.",
        "calendarValueType 속성이 'yearMonthDate' 인 경우에는 동작하지 않습니다 (오전/오후 컬럼이 표시되지 않음).",
        "calendarValueType 속성이 'yearMonth' 인 경우에는 동작하지 않습니다 (오전/오후 컬럼이 표시되지 않음)."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let calendarValueType = con_calendarValueType.getText();
    let ampmValue = par_ampm.getValue();

    let properties = {
        calendarValueType : calendarValueType,
        ampm : ampmValue
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);

    // calendarValueType 별로 setValue 포맷 보정 (createBasicDatePicker 기본 '20250101' 8자리)
    // yearMonth=6 / yearMonthDate=8 / yearMonthDateTime=12 / hourMinute=4
    if (calendarValueType === "yearMonth") {
        target1.setValue("202501");
    } else if (calendarValueType === "yearMonthDateTime") {
        target1.setValue("202501011030");
    } else if (calendarValueType === "hourMinute") {
        target1.setValue("1030");
    }
}



// ampm 컬럼이 존재할 때, 컬럼 itemArr[0]=AM, itemArr[1]=PM 의 label 텍스트 확인
scwin.getAmpmLabels = function () {
    if (!target1.colTypeObj || !target1.colTypeObj.hasOwnProperty('ampm')) {
        // validation: yearMonthDate / yearMonth 등 ampm 미적용 케이스
        wf_body_bottom.getObj("scwin").setReturnValue("[오전/오후 컬럼 라벨] 오전/오후 컬럼이 존재하지 않아 ampm 라벨이 적용되지 않음");
        return;
    }

    let ampmIdx = target1.colTypeObj['ampm'];
    let ampmCol = target1.childControlList[ampmIdx];

    if (!ampmCol || !ampmCol.itemArr || ampmCol.itemArr.length < 2) {
        wf_body_bottom.getObj("scwin").setReturnValue("[오전/오후 컬럼 라벨] 컬럼 정보 없음");
        return;
    }

    let amLabel = ampmCol.itemArr[0].label;  // value='AM' 셀의 라벨 (오전 라벨)
    let pmLabel = ampmCol.itemArr[1].label;  // value='PM' 셀의 라벨 (오후 라벨)

    // validation: 오전, 오후 순서로 2개의 라벨을 콤마(',') 로 구분 설정 / 값 미설정 시 기본값 '오전,오후'
    wf_body_bottom.getObj("scwin").setReturnValue("[1번째 라벨(오전, itemArr[0].label)] '" + amLabel + "' / [2번째 라벨(오후, itemArr[1].label)] '" + pmLabel + "'");

    // DOM 텍스트에서도 동일한 라벨이 출력되는지 확인
    let itembox = ampmCol.dom && ampmCol.dom.itembox;
    if (itembox) {
        let domTexts = [];
        let nodes = itembox.childNodes;
        for (let i = 0; i < nodes.length; i++) {
            let txt = (nodes[i].textContent || '').trim();
            if (txt) domTexts.push(txt);
        }
        wf_body_bottom.getObj("scwin").setReturnValue("[오전/오후 컬럼 DOM 텍스트 목록] [" + domTexts.join(', ') + "]");
    }
}



scwin.btn_getInfo_onclick = function (e) {
    scwin.getAmpmLabels();
}
